// src/builder/utils.ts
var LINE_HIGHLIGHT_PREFIX = "{";
var LINE_HIGHLIGHT_SUFFIX = "}";
var LINE_HIGHLIGHT_SEP = ",";
function formatLineHighlight(...highlights) {
  return highlights.map((highlight) => {
    switch (typeof highlight) {
      case "number": {
        return highlight.toString();
      }
      case "string": {
        return highlight;
      }
      default: {
        return `${highlight.from}-${highlight.to}`;
      }
    }
  }).join(LINE_HIGHLIGHT_SEP);
}
var LINE_NUMBERS_ATTRIBUTE = "line-numbers";
var CHAINED_ATTRIBUTES_SEP = ":";
export {
  CHAINED_ATTRIBUTES_SEP,
  LINE_HIGHLIGHT_PREFIX,
  LINE_HIGHLIGHT_SUFFIX,
  LINE_NUMBERS_ATTRIBUTE,
  formatLineHighlight
};
